WITH owned_todos AS (),
leaf_todos AS (
    SELECT * FROM owned_todos WHERE leaf
    AND COALESCE(due_dt, strt_dt) >= #{req.fromDate}
    AND COALESCE(strt_dt, due_dt) <= #{req.toDate}
)

mapper.select:

SELECT * FROM leaf_todos
WHERE todo_group = #{req.group}
ORDER BY COALESCE(due_dt, strt_dt) ASC NULLS LAST, created_at ASC, idx ASC
LIMIT #{req.size} OFFSET #{req.offset}

